592	    public void displayLoader(Boolean display) {
593	        int animationDuration = getResources().getInteger(
594	                android.R.integer.config_longAnimTime);
595	
596	        // Do not display animation if launcher button is already visible
597	        if (!display && launcherButton.getVisibility() == View.INVISIBLE) {
