599	
600	            // Animate transition from loader to launch button
601	            launcherButton.setAlpha(0);
602	            launcherButton.animate()
603	                    .alpha(1f)
604	                    .setDuration(animationDuration)
605	                    .setListener(null);
606	            loaderSpinner.animate()
607	                    .alpha(0f)
608	                    .setDuration(animationDuration)
609	                    .setListener(new AnimatorListenerAdapter() {
610	                        @Override
611	                        public void onAnimationEnd(Animator animation) {
612	                            loaderSpinner.setVisibility(View.GONE);
613	                            loaderSpinner.setAlpha(1);
614	                        }
615	                    });
616	        } else if (display) {
617	            launcherButton.setVisibility(View.INVISIBLE);
618	            loaderSpinner.setVisibility(View.VISIBLE);
619	        }
620	    }
