630	    private void displayKissBar(boolean display, boolean clearSearchText) {
631	        dismissPopup();
632	        // get the center for the clipping circle
633	        ViewGroup launcherButtonWrapper = (ViewGroup) launcherButton.getParent();
634	        int cx = (launcherButtonWrapper.getLeft() + launcherButtonWrapper.getRight()) / 2;
635	        int cy = (launcherButtonWrapper.getTop() + launcherButtonWrapper.getBottom()) / 2;
636	
637	        // get the final radius for the clipping circle
638	        int finalRadius = Math.max(kissBar.getWidth(), kissBar.getHeight());
639	
640	        if (display) {
641	            // Display the app list
642	            if (searchEditText.getText().length() != 0) {
643	                searchEditText.setText("");
644	            }
645	            resetTask();
646	
647	            // Needs to be done after setting the text content to empty
648	            isDisplayingKissBar = true;
649	
650	            searchTask = new ApplicationsSearcher(MainActivity.this);
651	            searchTask.executeOnExecutor(Searcher.SEARCH_THREAD);
652	
653	            // Reveal the bar
654	            if (android.os.Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP) {
655	                int animationDuration = getResources().getInteger(
656	                        android.R.integer.config_shortAnimTime);
657	
658	                Animator anim = ViewAnimationUtils.createCircularReveal(kissBar, cx, cy, 0, finalRadius);
659	                anim.setDuration(animationDuration);
660	                anim.start();
661	            }
662	            kissBar.setVisibility(View.VISIBLE);
663	
664	            // Display the alphabet on the scrollbar (#926)
665	            list.setFastScrollEnabled(true);
666	        } else {
667	            isDisplayingKissBar = false;
668	            // Hide the bar
669	            if (android.os.Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP) {
670	                int animationDuration = getResources().getInteger(
671	                        android.R.integer.config_shortAnimTime);
672	
673	                try {
674	                    Animator anim = ViewAnimationUtils.createCircularReveal(kissBar, cx, cy, finalRadius, 0);
675	                    anim.addListener(new AnimatorListenerAdapter() {
676	                        @Override
677	                        public void onAnimationEnd(Animator animation) {
678	                            kissBar.setVisibility(View.GONE);
679	                            super.onAnimationEnd(animation);
680	                        }
681	                    });
682	                    anim.setDuration(animationDuration);
683	                    anim.start();
684	                } catch (IllegalStateException e) {
685	                    // If the view hasn't been laid out yet, we can't animate it
686	                    kissBar.setVisibility(View.GONE);
687	                }
688	            } else {
689	                // No animation before Lollipop
690	                kissBar.setVisibility(View.GONE);
691	            }
692	
693	            if (clearSearchText) {
694	                searchEditText.setText("");
695	            }
696	
697	            // Do not display the alphabetical scrollbar (#926)
698	            // They only make sense when displaying apps alphabetically, not for searching
699	            list.setFastScrollEnabled(false);
700	        }
701	
702	        forwarderManager.onDisplayKissBar(display);
703	    }
