709	    /**
710	     * This function gets called on query changes.
711	     * It will ask all the providers for data
712	     * This function is not called for non search-related changes! Have a look at onDataSetChanged() if that's what you're looking for :)
713	     *
714	     * @param isRefresh whether the query is refreshing the existing result, or is a completely new query
715	     * @param query     the query on which to search
716	     */
717	    private void updateSearchRecords(boolean isRefresh, String query) {
718	        if (isRefresh && isViewingAllApps()) {
719	            // Refreshing while viewing all apps (for instance app installed or uninstalled in the background)
720	            Searcher searcher = new ApplicationsSearcher(this);
721	            searcher.setRefresh(isRefresh);
722	            runTask(searcher);
723	            return;
724	        }
725	
726	        resetTask();
727	        dismissPopup();
728	
729	        forwarderManager.updateSearchRecords(isRefresh, query);
730	
731	        if (query.isEmpty()) {
732	            systemUiVisibilityHelper.resetScroll();
733	        } else {
734	            QuerySearcher querySearcher = new QuerySearcher(this, query);
735	            querySearcher.setRefresh(isRefresh);
736	            runTask(querySearcher);
737	        }
738	    }
