278	    // Can (and will) break in any Android release.
279	    @SuppressLint("PrivateApi")
280	    @SuppressWarnings("CatchAndPrintStackTrace")
281	    private void displayNotificationDrawer() {
282	        @SuppressLint("WrongConstant") Object sbservice = mainActivity.getSystemService("statusbar");
283	        Class<?> statusbarManager;
284	        try {
285	            statusbarManager = Class.forName("android.app.StatusBarManager");
286	            Method showStatusBar;
287	            if (Build.VERSION.SDK_INT >= 17) {
288	                showStatusBar = statusbarManager.getMethod("expandNotificationsPanel");
289	            } else {
290	                showStatusBar = statusbarManager.getMethod("expand");
291	            }
292	            showStatusBar.invoke(sbservice);
293	        } catch (ClassNotFoundException e1) {
294	            e1.printStackTrace();
295	        } catch (NoSuchMethodException e1) {
296	            e1.printStackTrace();
297	        } catch (IllegalAccessException e1) {
298	            e1.printStackTrace();
299	        } catch (InvocationTargetException e1) {
