336	    /**
337	     * Are we allowed to run our AccessibilityService?
338	     */
339	    private boolean isAccessibilityServiceEnabled(Context context) {
340	        AccessibilityManager am = (AccessibilityManager) context.getSystemService(Context.ACCESSIBILITY_SERVICE);
341	        if (am == null) {
342	            return false;
343	        }
344	
345	        List<AccessibilityServiceInfo> enabledServices = am.getEnabledAccessibilityServiceList(AccessibilityServiceInfo.FEEDBACK_ALL_MASK);
346	
347	
348	        for (AccessibilityServiceInfo enabledService : enabledServices) {
349	            ServiceInfo enabledServiceInfo = enabledService.getResolveInfo().serviceInfo;
350	            if (enabledServiceInfo.packageName.equals(context.getPackageName()) && enabledServiceInfo.name.equals(LockAccessibilityService.class.getName()))
351	                return true;
352	        }
353	
354	        return false;
355	    }
