2	
3	import android.animation.Animator;
4	import android.animation.AnimatorListenerAdapter;
5	import android.content.SharedPreferences;
6	import android.os.Build;
7	import android.provider.Settings;
8	import android.util.Log;
9	import android.view.View;
10	import android.view.ViewGroup;
11	import android.widget.ListView;
12	
13	import fr.neamar.kiss.MainActivity;
14	import fr.neamar.kiss.R;
15	import fr.neamar.kiss.notification.NotificationListener;
16	
17	import static android.content.Context.MODE_PRIVATE;
18	
19	class Notification extends Forwarder {
20	    private final SharedPreferences notificationPreferences;
21	
22	    private SharedPreferences.OnSharedPreferenceChangeListener onNotificationDisplayed = new SharedPreferences.OnSharedPreferenceChangeListener() {
23	        @Override
24	        public void onSharedPreferenceChanged(SharedPreferences sharedPreferences, String packageName) {
25	            ListView list = mainActivity.list;
26	
27	            // A new notification was received, iterate over the currently displayed results
28	            // if one of them is for the package that just received a notification,
29	            // update the notification dot visual if required.
30	            //
31	            // This implementation should be more efficient than calling notifyDataSetInvalidated()
32	            // since we only iterate over the items currently displayed in the list
33	            // and do not rebuild them all, just toggle visibility if required.
34	            // Also, it means we get to display an animation, and that's cool :D
35	            updateDots(list, list.getLastVisiblePosition() - list.getFirstVisiblePosition(), packageName);
36	
37	            updateDots(mainActivity.favoritesBar, mainActivity.favoritesBar.getChildCount(), packageName);
38	
39	        }
40	    };
41	
42	    Notification(MainActivity mainActivity) {
43	        super(mainActivity);
44	        SharedPreferences notifsPrefBuilder = null;
45	
46	        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.JELLY_BEAN_MR2) {
47	            try {
48	                // Retrieve the preference iff permission has been given
49	                String allowedApps = Settings.Secure.getString(mainActivity.getContentResolver(), "enabled_notification_listeners");
50	                if (allowedApps != null && allowedApps.contains(mainActivity.getPackageName())) {
51	                    notifsPrefBuilder = mainActivity.getSharedPreferences(NotificationListener.NOTIFICATION_PREFERENCES_NAME, MODE_PRIVATE);
52	                } else {
53	                    // We don't have permission, make sure the SharedPreferences is empty to avoid displaying "ghost" notifications
54	                    mainActivity.getSharedPreferences(NotificationListener.NOTIFICATION_PREFERENCES_NAME, MODE_PRIVATE).edit().clear().apply();
55	                }
56	            } catch (Error e) {
57	                Log.i("Notification", "Unable to check for notification access: " + e.toString());
58	            }
59	        }
60	        notificationPreferences = notifsPrefBuilder;
61	    }
62	
63	    void onResume() {
64	        if (notificationPreferences != null) {
65	            notificationPreferences.registerOnSharedPreferenceChangeListener(onNotificationDisplayed);
66	        }
67	    }
68	
69	    void onPause() {
70	        if (notificationPreferences != null) {
71	            notificationPreferences.unregisterOnSharedPreferenceChangeListener(onNotificationDisplayed);
72	        }
73	    }
74	
75	    private void updateDots(ViewGroup vg, int childCount, String packageName) {
76	        for (int i = 0; i < childCount; i++) {
77	            View v = vg.getChildAt(i);
78	            final View notificationDot = v.findViewById(R.id.item_notification_dot);
79	            if (notificationDot != null && packageName.equals(notificationDot.getTag())) {
80	                boolean hasNotification = notificationPreferences.contains(packageName);
81	                animateDot(notificationDot, hasNotification);
82	            }
83	        }
84	    }
85	
86	    private void animateDot(final View notificationDot, boolean hasNotification) {
87	        int currentVisibility = notificationDot.getVisibility();
88	
89	        if (currentVisibility != View.VISIBLE && hasNotification) {
90	            // There is a notification and dot was not visible
91	            notificationDot.setVisibility(View.VISIBLE);
92	            notificationDot.setScaleX(0);
93	            notificationDot.setScaleY(0);
94	            notificationDot.animate().scaleX(1).scaleY(1).setListener(null);
95	        } else if (currentVisibility == View.VISIBLE && !hasNotification) {
96	            // There is no notification anymore, and dot was visible
97	            notificationDot.animate().scaleX(0).scaleY(0).setListener(new AnimatorListenerAdapter() {
98	                @Override
99	                public void onAnimationEnd(Animator animation) {
100	                    super.onAnimationEnd(animation);
101	                    notificationDot.setVisibility(View.GONE);
102	                    notificationDot.setScaleX(1);
103	                    notificationDot.setScaleY(1);
104	                }
105	            });
106	        }
107	    }
108	}
