120	    void onFavoriteChange() {
121	        ArrayList<Pojo> favoritesPojo = KissApplication.getApplication(mainActivity).getDataHandler().getFavorites();
122	        favCount = favoritesPojo.size();
123	
124	        ArrayList<ViewHolder> holders = new ArrayList<>(favCount);
125	
126	        ViewGroup favoritesBar = mainActivity.favoritesBar;
127	
128	        // Don't look for items after favIds length, we won't be able to display them
129	        for (int i = 0; i < favCount; i++) {
130	            Pojo favoritePojo = favoritesPojo.get(i);
131	            // Is there already a ViewHolder for this Pojo?
132	            ViewHolder viewHolder = findViewHolder(favoritePojo);
133	            if (viewHolder == null) {
134	                // If not, build a new one
135	                viewHolder = new ViewHolder(Result.fromPojo(mainActivity, favoritePojo), favoritePojo, mainActivity, mainActivity.favoritesBar);
136	                viewHolder.view.setOnClickListener(this);
137	                viewHolder.view.setOnLongClickListener(this);
138	                viewHolder.view.setOnTouchListener(this);
139	            }
140	
141	            holders.add(viewHolder);
142	
143	            // Check if view is different (we get null if beyond bounds, for instance when a new favorite was added)
144	            View currentView = favoritesBar.getChildAt(i);
145	            if (currentView != viewHolder.view) {
146	                if (viewHolder.view.getParent() != null) {
147	                    // We need to remove the view from its parent first
148	                    ((ViewGroup) viewHolder.view.getParent()).removeView(viewHolder.view);
149	                }
150	                favoritesBar.addView(viewHolder.view, i);
151	                // Remove old current view, which is now out of date. Useful for dynamic icons to ensure only the dynamic icon is updated, and everything else remains the same
152	                disposeOf(currentView);
153	                favoritesBar.removeView(currentView);
154	            }
155	
156	            if (notificationPrefs != null) {
157	                int dotColor = isExternalFavoriteBarEnabled() ? UIColors.getPrimaryColor(mainActivity) : Color.WHITE;
158	
159	                ImageView notificationDot = viewHolder.view.findViewById(R.id.item_notification_dot);
160	                if (notificationDot == null)
161	                    // Notification-less favorites don't have a dot
162	                    continue;
163	                notificationDot.setColorFilter(dotColor);
164	
165	                if (favoritePojo instanceof AppPojo) {
166	                    String packageName = ((AppPojo) favoritePojo).packageName;
167	                    notificationDot.setTag(packageName);
168	                    notificationDot.setVisibility(notificationPrefs.contains(packageName) ? View.VISIBLE : View.GONE);
169	                }
170	            }
171	        }
172	
173	        // Remove any leftover views from previous renders
174	        while (favoritesBar.getChildCount() > favCount) {
175	            Log.e("WTF", "Disposing");
176	            View toBeDisposed = favoritesBar.getChildAt(favCount);
177	            disposeOf(toBeDisposed);
178	            favoritesBar.removeViewAt(favCount);
179	        }
180	
181	        // kepp viewholders in memory for future recycling
182	        favoritesViews = holders;
183	        mDragEnabled = favCount > 1;
184	    }
